import{_ as e,o as a,c as r,a5 as i}from"./chunks/framework.BmD0ICqc.js";const s="/study/images/graphics/frame-pacing-intervals.svg",n="/study/images/graphics/frame-pacing-generated-intervals.svg",o="/study/images/graphics/frame-pacing-pipeline.svg",u=JSON.parse('{"title":"平均60 FPSでもカクつくのはなぜか — フレームタイムとフレームペーシング","description":"","frontmatter":{"title":"平均60 FPSでもカクつくのはなぜか — フレームタイムとフレームペーシング","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"同じ平均FPSでも画面が切り替わる間隔で見え方が変わる。フレーム生成を含む表示間隔を図と実践で比べ、CPU・GPU・提示のどこでカクついたかを調べる。","aliases":["フレームタイム","frame time","フレームペーシング","frame pacing","スタッター","stutter","Present","VSync","p99","PresentMon"],"verification":"Android Frame Pacing、DXGI Present、PresentMon 2.6.0、PIX、AMD FSR Frame Generation Swapchainの公式資料に照合（2026-11-13）"}},"headers":[],"relativePath":"graphics/optimization/frame-pacing.md","filePath":"graphics/optimization/frame-pacing.md"}'),d={name:"graphics/optimization/frame-pacing.md"};function l(p,t,c,g,h,m){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="平均60-fpsでもカクつくのはなぜか-—-フレームタイムとフレームペーシング" tabindex="-1">平均60 FPSでもカクつくのはなぜか — フレームタイムとフレームペーシング <a class="header-anchor" href="#平均60-fpsでもカクつくのはなぜか-—-フレームタイムとフレームペーシング" aria-label="Permalink to &quot;平均60 FPSでもカクつくのはなぜか — フレームタイムとフレームペーシング&quot;">​</a></h1><p>カメラを一定の速さで動かしていても、画面が一瞬止まり、そのあと大きく進むことがあります。1秒あたりに表示されたフレーム数が同じでも、次の絵が出るまでの時間は揃っているとは限りません。<strong>フレームペーシング</strong>は、ゲームの更新・描画と表示側のタイミングを合わせ、画面の切り替わりを狙った間隔に整えることです。<a href="https://developer.android.com/games/sdk/frame-pacing#background" target="_blank" rel="noreferrer">Android Frame Pacingの仕組み</a></p><h2 id="同じ平均60-fpsで、画面の切り替わり方を比べる" tabindex="-1">同じ平均60 FPSで、画面の切り替わり方を比べる <a class="header-anchor" href="#同じ平均60-fpsで、画面の切り替わり方を比べる" aria-label="Permalink to &quot;同じ平均60 FPSで、画面の切り替わり方を比べる&quot;">​</a></h2><p>固定120 Hzの仮想ディスプレイは約8.33 msごとに更新します。60 FPSを等間隔で表示するには、新しい絵に切り替える間隔を2更新分の約16.67 msにします。ここでは、<strong>ある絵に切り替わってから次の絵に切り替わるまでの時間</strong>を表示間隔と呼びます。同じ絵のままリフレッシュしても、新しい表示フレームには数えません。</p><p>2秒間の表示を二つ用意します。等間隔の例では全120フレームをそれぞれ2更新分だけ表示します。スパイクのある例では、31枚目と91枚目をそれぞれ6更新分（50 ms）表示し、その直後の4フレームは1更新分（約8.33 ms）ずつにします。どちらも合計は240更新分で、120フレーム ÷ 2秒 = <strong>60 FPS</strong>です。50 ms同じ絵が続くところでは動きが一瞬止まったように見え、その次の絵でまとめて進みます。</p><figure class="study-figure"><img src="'+s+'" alt="仮想120 Hzで500 msから583.33 msまでを比較する。上段は2更新ごとにフレーム31から35へ切り替わる。下段は31が6更新続き、その後の32から35は1更新ずつで切り替わる。両段とも10更新の間に5フレームを表示する。" width="760" height="302" loading="lazy"><figcaption>2秒間のうち、最初のスパイク周辺を拡大。横幅は表示していた時間です。<a href="/study/images/graphics/frame-pacing-intervals.svg" target="_blank" rel="noopener noreferrer">表示間隔の図を拡大</a></figcaption></figure><table tabindex="0"><thead><tr><th>指標</th><th style="text-align:right;">等間隔</th><th style="text-align:right;">スパイクあり</th></tr></thead><tbody><tr><td>平均FPS</td><td style="text-align:right;">60</td><td style="text-align:right;">60</td></tr><tr><td>平均表示間隔</td><td style="text-align:right;">16.67 ms</td><td style="text-align:right;">16.67 ms</td></tr><tr><td>p99表示間隔</td><td style="text-align:right;">16.67 ms</td><td style="text-align:right;">50.00 ms</td></tr><tr><td>最長の表示間隔</td><td style="text-align:right;">16.67 ms</td><td style="text-align:right;">50.00 ms</td></tr><tr><td>60 FPSの目安（約16.67 ms）を超えた間隔</td><td style="text-align:right;">0回</td><td style="text-align:right;">2回</td></tr></tbody></table><p>表は表示間隔を最後まで観測できた120フレームで集計しています。平均FPSはフレーム数を経過秒数で割って求めます。p99（99パーセンタイル）は、ここでは間隔を短い順に並べ、<code>ceil(0.99 × 件数)</code> 番目の値を取ります。120件なら119番目なので、50 msの間隔が1回だけの場合はp99に現れません。どの場面で何度起きたかを調べるには、最長値と時系列も見ます。</p><p>ブラウザ実践では、同じ時刻を使った二つの動きとグラフを見比べ、再生を止めてスパイクの前後を調べられます。数値は仮想120 Hzのモデルから計算します。<a href="/study/practice/graphics/frame-pacing-observation.html">表示間隔を見比べる実践</a></p><p><a href="/study/samples/graphics/frame-pacing-observation/index.html" target="_self">表示間隔の比較デモを開く</a></p><h2 id="フレーム生成でも表示間隔はそろえる" tabindex="-1">フレーム生成でも表示間隔はそろえる <a class="header-anchor" href="#フレーム生成でも表示間隔はそろえる" aria-label="Permalink to &quot;フレーム生成でも表示間隔はそろえる&quot;">​</a></h2><p>30 FPSで描いたAとBの間に、<a href="/study/graphics/postprocess/frame-generation.html">フレーム生成</a>で中間画像Mを作るとします。物体がAでは位置0、Mでは10、Bでは20にあり、順番も同じです。変えるのは各画像をいつ表示するかです。</p><p>等間隔ではA、M、Bを約16.67 msずつ離して表示します。不等間隔の例では、Aを25 ms保持し、Mを約8.33 msだけ表示してBに切り替えます。どちらもAからBまでは約33.33 msですが、不等間隔では<strong>止まって見える時間のあとに、MとBが立て続けに出ます</strong>。同じ距離を進む表示が長い間隔と短い間隔を交互に通るので、進む速さにむらがあるように見えます。</p><figure class="study-figure"><img src="'+n+'" alt="固定120 Hzで描画A、生成M、描画B、生成Nの4枚を比較。等間隔では各16.67 ms。不等間隔では描画AとBが各25 ms、生成MとNが各8.33 ms。どちらも約66.67 msに4枚を表示する。" width="760" height="295" loading="lazy"><figcaption>描画と生成の順番は共通です。表示間隔が違うと、生成した位置を見せる時間も変わります。<a href="/study/images/graphics/frame-pacing-generated-intervals.svg" target="_blank" rel="noopener noreferrer">フレーム生成の表示間隔の図を拡大</a></figcaption></figure><p>図の時間軸は、Aを表示し始めた時点からの相対時刻です。実際の表示では描画、生成、UI合成の完了を待つため、提示側が順番と間隔を調整します。例えばAMD FSR Frame Generationのスワップチェーンは、複数フレームの時間を使って目標の提示間隔を決め、生成画像と描画画像を順に提示します。どの絵が長く残るかは、処理の完了時刻やディスプレイの更新条件で変わります。<a href="https://gpuopen.com/manuals/fsr_sdk/techniques/frame-interpolation-swap-chain/#frame-pacing-and-presentation" target="_blank" rel="noreferrer">AMDのフレームペーシングと提示</a></p><p>実践の<strong>フレーム生成で間隔が不均等</strong>では、二つのレーンで同じ目印の位置を使います。時刻を20 ms付近で止めると、等間隔のレーンは中間画像へ進み、不等間隔のレーンはAのままです。グラフの高さは、その絵を保持する時間を示します。</p><h2 id="cpu、gpu、ディスプレイは別の時刻で動く" tabindex="-1">CPU、GPU、ディスプレイは別の時刻で動く <a class="header-anchor" href="#cpu、gpu、ディスプレイは別の時刻で動く" aria-label="Permalink to &quot;CPU、GPU、ディスプレイは別の時刻で動く&quot;">​</a></h2><p>ゲームはCPUで入力や状態を更新し、GPUに描画コマンドを送ります。GPUがその絵を描いている間に、CPUが次のフレームの準備を始めることもあります。アプリの <code>Present()</code> などの呼び出しは表示への要求です。描画完了やOSの合成、提示方式によって、実際に画面が切り替わる時刻は後になります。キューに入った絵が提示方式によって表示されずに破棄される場合もあります。<a href="https://learn.microsoft.com/en-us/windows/win32/api/dxgi/nf-dxgi-idxgiswapchain-present#flip-presentation-model-queue" target="_blank" rel="noreferrer">DXGI Presentとフリップキュー</a></p><figure class="study-figure"><img src="'+o+'" alt="固定60 Hzの例。CPUがフレームBの描画を依頼し、GPUがBを描いている間にCPUがCの準備を始める。Bが16.67 msの更新に間に合わないので画面はAのまま。33.33 msでB、50 msでCが表示される。" width="760" height="358" loading="lazy"><figcaption>固定60 Hzの例では、Bが予定した更新に間に合わず、Aが2更新分表示されます。<a href="/study/images/graphics/frame-pacing-pipeline.svg" target="_blank" rel="noopener noreferrer">CPU・GPU・画面の図を拡大</a></figcaption></figure><p>図は固定リフレッシュレートで、更新の境目に絵を切り替える簡略モデルです。Bを表示する予定の時刻にGPUの仕事が終わっていなければ、画面にはAがもう1更新分残ります。実機ではVSync、可変リフレッシュレート（VRR）、OSの合成や提示方式によってタイミングが変わります。例えばVRRは対応範囲内で更新周期を変えられるので、固定周期のように表示間隔を一律に数える方法は適しません。<a href="https://developer.android.com/games/sdk/frame-pacing#background" target="_blank" rel="noreferrer">Androidの表示パイプライン</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3ddxgi/variable-refresh-rate-displays" target="_blank" rel="noreferrer">DXGIの可変リフレッシュレート</a></p><p>「フレームタイム」と書かれたグラフでは、先に何から何まで測った値かを確かめます。</p><table tabindex="0"><thead><tr><th>どの時間か</th><th>測る範囲</th><th>分かること</th></tr></thead><tbody><tr><td>CPU側のフレーム間隔</td><td>このフレームのCPU処理開始から次の開始まで</td><td>CPU側の更新ペース。実行に加え待ちも入る</td></tr><tr><td>CPU・GPUの実行時間</td><td>各プロセッサーでフレームの仕事をしていた区間</td><td>どの処理が長いか。CPUとGPUで区間が重なる場合がある</td></tr><tr><td>Present間隔</td><td>アプリが表示要求を出してから次の要求まで</td><td>アプリ側の提示要求のペース</td></tr><tr><td>表示間隔</td><td>この絵が表示されてから次の絵に切り替わるまで</td><td>絵が更新された間隔。画面側のカクつきを追う手掛かり</td></tr></tbody></table><h2 id="windowsでカクついた区間を追う" tabindex="-1">Windowsでカクついた区間を追う <a class="header-anchor" href="#windowsでカクついた区間を追う" aria-label="Permalink to &quot;Windowsでカクついた区間を追う&quot;">​</a></h2><ol><li><strong>再現条件を揃える。</strong> 同じビルド、カメラ経路、画面設定で記録します。リフレッシュレート、VSync、VRR、FPS制限を控え、読み込み直後と再訪時で挙動が違う場合は両方記録します。</li><li><strong>表示が長く止まった区間を見つける。</strong> PresentMonのCSVを対象プロセスとスワップチェーンで絞ります。バージョン2.6.0の既定CSVでは、<code>MsBetweenDisplayChange</code> が、現在の絵に切り替わるまでに<strong>直前の絵</strong>が表示されていた時間です。数値のある行を時系列で見て、表示要求の間隔を示す <code>MsBetweenPresents</code> と比べます。要求の間隔が安定していて表示側の間隔が跳ねる場合は、GPUや表示経路での遅れを調べます。同じCSVでCPU側のフレーム間隔は <code>MsBetweenAppStart</code>、CPUとGPUの稼働時間は <code>MsCPUBusy</code> と <code>MsGPUBusy</code> です。<code>--v2_metrics</code> を指定したCSVでは、各行の絵の表示時間は <code>DisplayedTime</code> に出ます。<a href="https://github.com/GameTechDev/PresentMon/blob/v2.6.0/README-ConsoleApplication.md#csv-columns" target="_blank" rel="noreferrer">PresentMon 2.6.0の指標定義</a> · <a href="https://github.com/GameTechDev/PresentMon/blob/v2.6.0/PresentMon/CsvOutput.cpp#L530-L605" target="_blank" rel="noreferrer">CSVヘッダーの実装</a></li><li><strong>前後の普通のフレームと比較する。</strong> Direct3D 12なら、PIXのTiming CaptureでCPUスレッドとGPUキューを同じ時刻軸に並べます。CPU側で長いイベントや待ちがないか、GPU側で描画・コピーの区間が延びていないか、送信からGPUの実行開始までの待ちが増えていないかを順に見ます。CPUとGPUは並行して進むため、両方の実行時間を足しても表示間隔にはなりません。<a href="https://learn.microsoft.com/en-us/windows/pix/timing-captures/timing-captures-overview" target="_blank" rel="noreferrer">PIX Timing Captures</a></li><li><strong>原因候補を一つ変え、同じ条件で計り直す。</strong> 例えばマップの境目でだけCPUの待ちが増えるなら、ファイル読み込みのマーカーと待ち始めの時刻を照らし合わせます。CPUとGPUの仕事量が普段通りなら、表示キューの待ちや提示方式の変化を確認します。修正前後は平均FPSに加え、同じ場面で表示間隔のスパイクが短くなったか、回数が減ったかを比べます。<a href="/study/graphics/optimization/basics.html">GPU最適化の基礎</a></li></ol><p>描画が終わった絵をどの順番で出すか、表示の途中で絵を替えると何が見えるかは、<a href="/study/graphics/optimization/swap-chain-and-vsync.html">スワップチェーンとVSync</a>で扱います。</p><p><a href="/study/practice/graphics/vsync-vrr-observation.html">VSyncオフ・オン・VRRの比較実践</a>では、同じ描画完了時刻で、走査途中の切り替え、固定周期での再表示、可変周期での待ちを比べられます。</p><p>関連項目は<a href="/study/guide/low-level/input-and-game-loop.html">入力とゲームループ</a>と<a href="/study/graphics/optimization/tools.html">デバッグ・プロファイリングツール</a>です。</p><p>CPU側のスパイクを関数やスレッドまで追う手順は、<a href="/study/tools/profiling/cpu-profiling.html">CPU プロファイリング</a>で確認できます。</p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li><p>2秒で120枚を表示したとき、平均FPSだけで50 msの停止があったか判断できますか。</p><details class="details custom-block"><summary>解答</summary><p>平均FPSは60です。50 msの間隔があったかは、表示間隔の時系列や最長値を調べます。</p></details></li><li><p>生成Mの位置が同じでも、Aを長く保持してMを短く表示するとどう見えますか。</p><details class="details custom-block"><summary>解答</summary><p>Aの位置で長く止まり、MとBが短い間隔で続きます。表示枚数が同じでも、動く速さにむらがあるように見えます。</p></details></li></ol><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/practice/graphics/frame-pacing-observation.html">同じ60 FPSで表示間隔を比べる</a>で、表示間隔と目印の動きを同じ時刻で調べる。</li><li><a href="/study/graphics/postprocess/frame-generation.html">フレーム生成</a>で、中間画像を作る仕組みと入力への反応を確認する。</li><li><a href="/study/learn/roadmap.html?node=gfx-optimization#graphics">3DCG・描画ロードマップの「GPU最適化」</a></li></ul>',32)])])}const P=e(d,[["render",l]]);export{u as __pageData,P as default};
